691| /**
692|  * POST /sessions/driver — headless driver start/stop/restart, REUSING `quay driver` (runDriver).
693|  * Body: {verb: start|stop|restart, kind: promotion|worker}. Any other verb/kind (interactive
694|  * manager/outer/inner, status, drain) ⇒ 400 (AC3). The valid path delegates to runDriver and echoes
695|  * its structured result (ok/reason/stdout/stderr/exitCode) — never a reimplemented lifecycle.
696|  */
697| export async function handleDriverLifecycle(req: IncomingMessage, res: ServerResponse, cfg: ServePageCfg): Promise<void> {
698|   const raw = await readBody(req);
699|   const body = parsePostBody(raw, req.headers["content-type"] ?? "");
700|   const spec = driverActionSpec(body.verb, body.kind);
701|   if (spec == null) {
702|     writeJson(res, 400, { ok: false, reason: `invalid driver action (verb ∈ ${WEB_DRIVER_VERBS.join("|")}, kind ∈ ${WEB_DRIVER_KINDS.join("|")})`, verb: body.verb ?? null, kind: body.kind ?? null });
703|     return;
704|   }
705|   // Forward --kind into the supervisor argv (runDriver's `rest` carries the user flags verbatim; the
706|   // CLI gets --kind from `rest`, the web layer must pass it explicitly). ⛔ omitting it makes the
707|   // supervisor default to promotion — a web "worker" action would silently hit the promotion driver.
708|   const r = runDriver(spec.verb, spec.kind, ["--kind", spec.kind], cfg.workspaceRoot);
709|   writeJson(res, 200, { ok: r.ok, verb: spec.verb, kind: spec.kind, stdout: r.stdout, stderr: r.stderr, exitCode: r.exitCode, reason: r.reason });
710| }
