437|   rootFlag: string | undefined,
438| ): DriverRunResult {
439|   const inv = resolveDriverInvocation(verb, kind, rest, rootFlag);
440|   if (inv.failure !== null) return inv.failure;
441|   const r = spawnSync(process.execPath, inv.spawnArgs, { encoding: "utf8" });
442|   const stdout = withWorkerInstrumentReadings(verb, kind, r.stdout ?? "", inv.root, inv.kernelPath);
443|   return { ok: true, reason: null, stdout, stderr: r.stderr ?? "", exitCode: r.status ?? 1 };
444| }
